import csv
import html
import json
import shutil
from collections import Counter
from pathlib import Path
from run_scores_v3 import DIMENSIONS, summarize

ROOT=Path(__file__).resolve().parent
Q={'high_quality':'高质量','low_quality':'低质量'}
T={'marketing':'营销/品牌介绍','commerce':'电商','operations':'业务管理/数据','content':'内容/作品集','other':'其他','non_ui':'非界面'}
escape=lambda value:html.escape(str(value))
def read(name):return json.loads((ROOT/name).read_text(encoding='utf-8-sig'))
results=read('jev_scores_v3.json')
with (ROOT/'samples.csv').open(encoding='utf-8-sig',newline='') as handle:samples={x['sample_id']:x for x in csv.DictReader(handle)}
evidence={x['sample_id']:x for x in read('quality_evidence_luna.json')}
captions={x['sample_id']:x for x in read('captions_luna.json')}
assert len(results)==50 and {x['sample_id'] for x in results}==set(samples)
export=[];cards=[];client=[]
for item in sorted(results,key=lambda x:x['sample_id']):
    sid=item['sample_id'];scores=item['scores'];answers=item['response']['answers'];sample=samples[sid]
    assert summarize(answers)[0]==scores
    export.append({'sample_id':sid,'quality':Q[item['quality']],'type':T[item['type']],'total':round(item['total'],1),**{name:round(value,1) for name,value in scores.items()}})
    client.append({'id':sid,'type':item['type'],'valid':answers['valid_ui']['noul'],'total':item['total'],**scores})
    score_rows=''.join(f'<div class="metric"><div><span>{dim["label"]}</span><strong>{scores[name]:.1f}<small> / 100</small></strong></div><div class="track"><i style="width:{scores[name]:.3f}%"></i></div></div>' for name,dim in DIMENSIONS.items())
    details=''.join(f'<p><b>{label}：</b>{escape("；".join(evidence[sid].get(key,[])) if isinstance(evidence[sid].get(key),list) else evidence[sid].get(key,""))}</p>' for key,label in [('layout_hierarchy','信息层级'),('alignment_spacing','布局与间距'),('visual_consistency','视觉一致性'),('learnable_detail','可学习细节'),('limitations','限制与不确定')])
    confidences=' · '.join(f'{dim["label"]} {answers[name]["confidence"]:.2f}' for name,dim in DIMENSIONS.items())
    cards.append(f'''<article id="{sid}" data-id="{sid}"><div class="card-head"><b>{sid}</b><div class="tags"><span class="quality {item['quality']}">{Q[item['quality']]}</span><span class="type">{T[item['type']]}</span></div></div><a href="{escape(sample['sample_path'])}" target="_blank"><img loading="lazy" src="previews/{sid}.jpg" alt="{sid} 图片"></a><div class="total"><span>质量总分</span><strong>{item['total']:.1f}<small> / 100</small></strong></div><div class="metrics">{score_rows}</div><p class="reason">{escape('；'.join(item['reasons']))}</p><details><summary>查看视觉依据与置信度</summary><p>{escape(captions[sid]['caption'])}</p>{details}<p class="internal">各项置信度（不计入质量分）：{escape(confidences)}<br>有效界面概率 {answers['valid_ui']['noul']:.2f} · 类型置信度 {answers['page_use']['confidence']:.2f}</p></details></article>''')
with (ROOT/'scores_v3.csv').open('w',encoding='utf-8-sig',newline='') as handle:
    writer=csv.DictWriter(handle,fieldnames=list(export[0]));writer.writeheader();writer.writerows(export)
(ROOT/'scores_v3.json').write_text(json.dumps(export,ensure_ascii=False,indent=2),encoding='utf-8')
minimal=[{key:item[key] for key in ('sample_id','quality','type')} for item in export]
(ROOT/'final_classification_v3.json').write_text(json.dumps(minimal,ensure_ascii=False,indent=2),encoding='utf-8')
with (ROOT/'final_classification_v3.csv').open('w',encoding='utf-8-sig',newline='') as handle:
    writer=csv.DictWriter(handle,fieldnames=['sample_id','quality','type']);writer.writeheader();writer.writerows(minimal)
summary={'sample_count':50,'quality_counts':dict(Counter(Q[x['quality']] for x in results)),'type_counts':dict(Counter(T[x['type']] for x in results)),'mean_total':round(sum(x['total'] for x in results)/50,1),'min_total':round(min(x['total'] for x in results),1),'max_total':round(max(x['total'] for x in results),1),'mean_dimensions':{name:round(sum(x['scores'][name] for x in results)/50,1) for name in DIMENSIONS},'top_five':[{'sample_id':x['sample_id'],'total':round(x['total'],1)} for x in sorted(results,key=lambda x:x['total'],reverse=True)[:5]],'rule':'score_rule_v3.json','human_calibrated':False,'models':dict(Counter(x['response']['model'] for x in results)),'usage':{}}
for item in results:
    for name,value in item['response'].get('usage',{}).items():
        if isinstance(value,(int,float)):summary['usage'][name]=summary['usage'].get(name,0)+value
(ROOT/'score_summary_v3.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
template=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>前端图片筛选 · 100 分质量评分</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f3ef;color:#242820;font:15px/1.6 system-ui,sans-serif}header{padding:22px 4vw 18px;background:#fff;border-bottom:1px solid #dfe2d8;position:sticky;top:0;z-index:10}h1{font-size:25px;margin:0}header p{margin:6px 0;color:#62695d}.stats{display:flex;gap:22px;flex-wrap:wrap;font-size:17px;font-weight:600;margin:10px 0}.formula{font-size:13px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px}select,button,input{font:inherit;padding:7px 10px;border:1px solid #cfd6c5;border-radius:7px;background:#fff;color:#242820}button{cursor:pointer}input{width:72px}label{font-size:13px;color:#62695d}.count{font-size:13px;color:#62695d}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(350px,100%),1fr));gap:20px;padding:24px 4vw}article{background:#fff;border:1px solid #dfe2d8;border-radius:12px;padding:16px}.card-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:12px}.tags{display:flex;gap:7px;flex-wrap:wrap}.tags span{font-size:12px;font-weight:600;padding:4px 8px;border-radius:6px}.high_quality{background:#e8f2df;color:#315618}.low_quality{background:#fce9df;color:#974726}.type{background:#eff0ec;color:#575e50}img{width:100%;height:300px;object-fit:contain;background:#eeefea;border-radius:6px}.total{display:flex;align-items:center;justify-content:space-between;padding:13px 0;border-bottom:1px solid #e5e8df}.total strong{font-size:32px;line-height:1.2;letter-spacing:-1px;color:#365b26}.total small{font-size:13px;color:#818776;letter-spacing:0;font-weight:400}.metrics{padding-top:10px}.metric{margin:10px 0}.metric>div:first-child{display:flex;align-items:center;justify-content:space-between;font-size:13px}.metric strong{font-size:15px;font-variant-numeric:tabular-nums}.metric small{font-size:11px;color:#969c8d;font-weight:400}.track{height:4px;background:#edf0e8;border-radius:4px;margin-top:5px;overflow:hidden}.track i{height:100%;display:block;background:#7c9b65;border-radius:4px}.reason{font-size:13px;color:#80613f;min-height:38px}summary{cursor:pointer;font-weight:600;font-size:13px;color:#416432}details p{font-size:13px}p.internal{color:#777;font-size:12px;border-top:1px solid #ddd;padding-top:10px}article[hidden]{display:none}footer{padding:0 4vw 30px;color:#777;font-size:13px}@media(max-width:700px){header{position:static}.toolbar{gap:8px}h1{font-size:22px}}
</style></head><body><header><h1>前端图片筛选 · 100 分质量评分</h1><div class="stats"><span id="high">高质量 HIGHCOUNT 张</span><span id="low">低质量 LOWCOUNT 张</span><span>平均总分 MEAN / 100</span></div><p class="formula">总分 = 布局 25% + 层级 20% + 可读性 15% + 一致性 20% + 可学习性 20%</p><p class="formula">高质量：总分达到门槛、可学习性 ≥ 70、其余分项 ≥ 60，且有效界面概率 ≥ 0.7；非界面归低质量。</p><div class="toolbar"><select id="quality" aria-label="质量筛选"><option value="all">全部质量</option><option value="high_quality">高质量</option><option value="low_quality">低质量</option></select><select id="type" aria-label="类型筛选"><option value="all">全部类型</option>TYPEOPTIONS</select><select id="sort" aria-label="分数排序"><option value="total">按总分排序</option>SORTOPTIONS<option value="id">按样本编号</option></select><select id="direction" aria-label="排序方向"><option value="desc">从高到低</option><option value="asc">从低到高</option></select><label>高质量总分门槛 <input id="threshold" type="number" min="0" max="100" step="1" value="75"></label><button id="download">下载当前结果</button><span id="count" class="count"></span></div></header><main>CARDS</main><footer>50 张固定随机样本。分数由 Luna 的视觉描述及质量观察交给 Jev 判断，各项满分 100，置信度单独保留。阈值尚未经人工校准；所有原图与历次实验结果保留。调整总分门槛只重新计算标签，不调用 API。</footer><script>
const records=RECORDS,typeNames=TYPENAMES,byId=new Map(records.map(r=>[r.id,r]));const q=document.getElementById('quality'),t=document.getElementById('type'),s=document.getElementById('sort'),d=document.getElementById('direction'),threshold=document.getElementById('threshold'),main=document.querySelector('main');let visible=[];
function cutoff(){const n=Number(threshold.value);return Number.isFinite(n)?Math.max(0,Math.min(100,n)):75}
function quality(r){return r.type!=='non_ui'&&r.valid>=.7&&r.total>=cutoff()&&r.learnability>=70&&['layout','hierarchy','readability','consistency'].every(k=>r[k]>=60)?'high_quality':'low_quality'}
function reason(r){let a=[];if(r.type==='non_ui'||r.valid<.7)a.push('有效前端界面信息不足');if(r.total<cutoff())a.push('总分低于'+cutoff());if(r.learnability<70)a.push('数据可学习性低于70');for(const [k,n] of [['layout','布局与间距'],['hierarchy','信息层级'],['readability','可读性'],['consistency','视觉一致性']])if(r[k]<60)a.push(n+'低于60');return a.join('；')||'总分及各项最低要求均达标'}
function apply(){let high=0;visible=[];for(const a of main.querySelectorAll('article')){const r=byId.get(a.dataset.id),v=quality(r),tag=a.querySelector('.quality');if(v==='high_quality')high++;tag.className='quality '+v;tag.textContent=v==='high_quality'?'高质量':'低质量';a.querySelector('.reason').textContent=reason(r);a.hidden=!(q.value==='all'||v===q.value)||!(t.value==='all'||r.type===t.value)}const sorted=[...main.querySelectorAll('article')].sort((a,b)=>{const x=byId.get(a.dataset.id),y=byId.get(b.dataset.id);if(s.value==='id')return x.id.localeCompare(y.id);return (d.value==='desc'?y[s.value]-x[s.value]:x[s.value]-y[s.value])||x.id.localeCompare(y.id)});for(const a of sorted){main.appendChild(a);if(!a.hidden)visible.push(byId.get(a.dataset.id))}document.getElementById('high').textContent='高质量 '+high+' 张';document.getElementById('low').textContent='低质量 '+(50-high)+' 张';document.getElementById('count').textContent='显示 '+visible.length+' / 50 张'}
for(const control of [q,t,s,d,threshold])control.addEventListener('change',apply);
document.getElementById('download').addEventListener('click',()=>{const header=['样本编号','质量','类型','总分','布局与间距','信息层级','可读性','视觉一致性','数据可学习性','总分门槛'];const rows=visible.map(r=>[r.id,quality(r)==='high_quality'?'高质量':'低质量',typeNames[r.type],...['total','layout','hierarchy','readability','consistency','learnability'].map(k=>r[k].toFixed(1)),cutoff()]);const csv='\uFEFF'+[header,...rows].map(row=>row.map(value=>'"'+String(value).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='前端图片分数_门槛'+cutoff()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});apply();
</script></body></html>'''
type_options=''.join(f'<option value="{key}">{label}</option>' for key,label in T.items())
sort_options=''.join(f'<option value="{name}">按{dim["label"]}排序</option>' for name,dim in DIMENSIONS.items())
page=template.replace('HIGHCOUNT',str(summary['quality_counts'].get('高质量',0))).replace('LOWCOUNT',str(summary['quality_counts'].get('低质量',0))).replace('MEAN',str(summary['mean_total'])).replace('TYPEOPTIONS',type_options).replace('SORTOPTIONS',sort_options).replace('CARDS',''.join(cards)).replace('RECORDS',json.dumps(client,ensure_ascii=False).replace('<','\\u003c')).replace('TYPENAMES',json.dumps(T,ensure_ascii=False))
page=page.replace('各项满分 100，置信度单独保留。','各项满分 100，置信度单独保留。显示保留一位小数，标签按未舍入分数计算。')
archive=ROOT/'review_round2.html'
if (ROOT/'review.html').exists() and not archive.exists():shutil.copy2(ROOT/'review.html',archive)
(ROOT/'review.html').write_text(page,encoding='utf-8')
assert page.count('<article ')==50 and page.count('class="metric"')==250
print(json.dumps(summary,ensure_ascii=False,indent=2))
